INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿A qué se denomina "problemática penal" según los textos de las cátedras?', '["Únicamente al estudio de las leyes escritas en el Código Penal.", "A un conjunto de problemas sistemáticamente ordenados en torno al crimen, el criminal, la víctima y la pena .", "Al proceso administrativo de las cárceles federales.", "A la relación entre el abogado defensor y su cliente."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', 'Para que un problema científico penal encuentre respuesta, ¿cuál es uno de los requisitos de su formulación?', '["Debe ser tratado en el vacío absoluto.", "Debe estar contextualmente ubicado e interrelacionado con el resto de los problemas .", "No debe poseer presupuestos ideológicos.", "Debe resolverse únicamente mediante la intuición."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿En qué consiste el "tratamiento interdisciplinario" de la problemática penal?', '["En que el derecho penal monopolice todas las respuestas.", "En evitar reduccionismos epistemológicos integrando respuestas de diversos niveles de conocimiento como el psíquico, biológico y cultural .", "En el estudio aislado de cada ciencia sin comunicación entre sí.", "En aplicar únicamente la ley penal sin considerar otras ciencias."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué sostiene el racionalismo respecto al delito?', '["Que es un fenómeno natural producto de una enfermedad.", "Que es un ente racional donde el sujeto elige el mal mediante su razón .", "Que solo se conoce a través de la experiencia sensorial.", "Que el delincuente no tiene libre albedrío."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Cómo define Francisco Carrara al delito desde la Escuela Clásica?', '["Como un fenómeno biológico y social.", "Como la infracción de la ley del Estado resultante de un acto externo del hombre, moralmente imputable y políticamente dañoso .", "Como un síntoma de peligrosidad criminal.", "Como una construcción destinada a seleccionar personas marginadas."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Cuál es el método utilizado por la Escuela Clásica?', '["El método inductivo y experimental.", "El método deductivo, especulativo o lógico-abstracto .", "La observación de casos particulares en el laboratorio.", "El análisis sociológico de las masas."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', 'Según Carrara, ¿en qué se sustenta la responsabilidad penal?', '["En la peligrosidad del sujeto.", "En el libre albedrío y la imputabilidad moral .", "En la defensa social del Estado.", "En el determinismo psíquico."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Cuál es la nota fundamental de la Escuela Positiva iniciada por Lombroso?', '["El reconocimiento del libre albedrío absoluto.", "Que el delincuente es un defectuoso psíquico y el delito es producto de causas antropológicas, físicas y sociales .", "Que la pena debe ser solo retributiva.", "El estudio del delito como un ente jurídico abstracto."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es el "delito natural" para Rafael Garófalo?', '["La violación de cualquier ley estatal.", "La lesión de los sentimientos de piedad y probidad según la medida en que se encuentran en las razas humanas superiores .", "Un comportamiento que no merece pena.", "Un pecado religioso castigado por el Estado."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué autor es el creador de los "sustitutivos penales"?', '["Cesare Beccaria.", "Enrico Ferri .", "Hans Welzel.", "Sebastián Soler."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué sostiene la "Tercera Escuela" (Italia) respecto al libre albedrío?', '["Lo afirma categóricamente.", "Lo niega, siguiendo a la Escuela Positiva, pero mantiene la responsabilidad moral para los imputables .", "Considera que no tiene importancia para el Derecho Penal.", "Dice que solo existe en los delitos políticos."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Cuál es la función de la pena para las "Teorías Absolutas" o de la Retribución?', '["Prevenir futuros delitos.", "La retribución o castigo justo por el mal causado, hallando su justificación en sí misma .", "Resocializar al delincuente.", "Servir de ejemplo a la sociedad."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', 'Según Hegel (retribución jurídica), ¿qué es la pena?', '["Un tratamiento para una enfermedad.", "La negación de la negación del derecho (el delito), lo que implica la afirmación del derecho .", "Un medio para intimidar a la población.", "Un mal innecesario que debe ser abolido."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿En qué consiste la "prevención general negativa"?', '["En educar al delincuente dentro de la cárcel.", "En la intimidación de la sociedad mediante la amenaza y ejecución de la pena para que no se delinca .", "En reparar el daño causado a la víctima.", "En otorgar premios a los ciudadanos honestos."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Cuál es el fin de la "prevención especial positiva"?', '["Inspirar terror en el delincuente.", "El mejoramiento, reforma o resocialización del delincuente .", "Castigar al autor por su pecado.", "Mantener el orden jurídico sin importar el sujeto."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué son las "medidas de seguridad"?', '["Penas más fuertes para delitos graves.", "Instrumentos coercitivos basados en la peligrosidad del sujeto, aplicables a inimputables o peligrosos, con fin de cura o tutela [22, 39-41].", "Impuestos que se cobran para financiar a la policía.", "Reglas de tránsito para evitar accidentes."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué carácter tiene la pena según Zaffaroni?', '["Es puramente retributiva.", "Es un hecho político de poder que el derecho penal debe limitar y contener .", "Es un tratamiento médico obligatorio.", "Es la única forma de justicia divina en la tierra."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Cuál es la diferencia entre pena y medida de seguridad para la tesis de la "diferenciación"?', '["No hay diferencia, son lo mismo.", "La pena es retribución fundada en culpabilidad; la medida es prevención fundada en peligrosidad .", "La pena es para menores y la medida para adultos.", "La medida es siempre perpetua y la pena siempre temporal."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué establece el sistema "vicarial" de penas y medidas de seguridad?', '["Que solo se puede aplicar una de las dos.", "Que se pueden aplicar ambas sucesiva o conjuntamente, computando el tiempo de la medida como cumplimiento de la pena .", "Que el juez elige por sorteo cuál aplicar.", "Que las penas se aplican solo a extranjeros."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Cuál de estos es un carácter propuesto por la doctrina para la pena?', '["Debe ser secreta y arbitraria.", "Debe ser legal, judicial, personal e igualitaria .", "Debe poder heredarse por los hijos del reo.", "Debe ser siempre la pena de muerte."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Dónde se ubica el principio de "Legalidad" en la Constitución Nacional?', '["En el Artículo 14.", "En el Artículo 18 [15, 51-54].", "En el Artículo 1.", "En el Artículo 75 inciso 12."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué establece el principio de "Reserva" (Art. 19 CN)?', '["Que el Estado puede prohibir lo que quiera sin ley.", "Que las acciones privadas que no dañen a terceros están exentas de la autoridad de los magistrados y nadie está obligado a hacer lo que la ley no manda [53, 55-57].", "Que los jueces pueden crear delitos por analogía.", "Que el Código Penal es secreto."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Cuál es la única fuente directa y conocimiento del Derecho Penal argentino?', '["La costumbre.", "La Ley Penal .", "La jurisprudencia.", "La doctrina de los autores famosos."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es una "ley penal en blanco"?', '["Una ley que no tiene palabras escritas.", "Aquella que fija una pena pero remite la descripción de la conducta prohibida a otra norma o reglamento .", "Una ley que solo se aplica a los blancos.", "Una ley que ha sido derogada por el Congreso."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Cuál es el principio general de la ley penal en el tiempo?', '["La retroactividad de la ley más severa.", "La irretroactividad de la ley penal, salvo que sea más benigna [62, 67-69].", "Que las leyes duran para siempre.", "Que se aplica la ley que el juez prefiera."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué sucede si durante la condena se dicta una ley más benigna (Art. 2 CP)?', '["El reo debe cumplir la pena original.", "La pena se limitará a la establecida por la nueva ley, operando de pleno derecho .", "Solo se aplica si el preso tiene buena conducta.", "La ley más benigna no existe en Argentina."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Cuál es el principio fundamental de aplicación de la ley penal en el espacio en Argentina?', '["Principio de nacionalidad.", "Principio de territorialidad (Art. 1 CP) .", "Principio universal absoluto.", "Principio de reciprocidad comercial."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué establece el "Principio Real o de Defensa"?', '["Que la ley sigue al argentino en el exterior.", "Que el Código se aplica a delitos cometidos en el extranjero cuyos efectos deban producirse en territorio argentino .", "Que el Estado puede invadir otros países si hay delitos.", "Que los diplomáticos no tienen leyes."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es la extradición pasiva?', '["Cuando Argentina reclama a un delincuente a otro país.", "Cuando otro Estado requiere a Argentina la entrega de un individuo que se encuentra en su territorio .", "Cuando el preso se entrega voluntariamente.", "El intercambio de prisioneros de guerra."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué prohíbe el principio de "Especialidad" en la extradición?', '["Entregar a personas con títulos universitarios.", "Perseguir al extraditado por un delito distinto al que motivó la extradición [76, 78-80].", "Que el juicio dure más de un año.", "Que el abogado sea extranjero."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Cuál es la definición dogmática de delito más aceptada?', '["Un pecado social castigado por el rey.", "Una conducta típica, antijurídica y culpable [73, 81-84].", "Una acción que molesta al legislador.", "Cualquier hecho que produzca un daño material."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es la "acción" o conducta para el Derecho Penal?', '["Un simple pensamiento criminal.", "Un comportamiento humano voluntario que se refleja en el mundo externo .", "El movimiento de un animal que causa daño.", "Un suceso de la naturaleza como un rayo."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Cuál es una causa que excluye la acción por falta de voluntad?', '["El dolo eventual.", "La fuerza física irresistible (vis absoluta) .", "La embriaguez leve.", "El miedo a la oscuridad."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué diferencia a los "actos reflejos" de la conducta?', '["Son conductas planeadas con mucho tiempo.", "Son movimientos puramente somáticos sin intervención de la voluntad ante un estímulo exterior .", "Son delitos de omisión impropia.", "Tienen siempre un fin delictivo."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es el "estado de inconsciencia" (Art. 34 inc 1 CP) en relación a la acción?', '["Una forma de dolo.", "Una causa de exclusión de la acción si es total o de la imputabilidad si es perturbación profunda .", "El sueño después de trabajar.", "Una excusa absolutoria."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es la "tipicidad"?', '["El juicio de valor sobre la maldad del autor.", "La adecuación de una conducta a la descripción legal de un delito (tipo) .", "La facultad del juez de perdonar.", "El nombre del artículo del Código Penal."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué elementos integran el "tipo objetivo"?', '["Solo la intención del autor.", "La descripción de la conducta, los sujetos, el objeto, el resultado y el nexo causal .", "La moral del juez.", "El pasado del delincuente."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué son los "elementos normativos" del tipo?', '["Números de artículos.", "Aquellos que requieren una valoración jurídica o cultural para ser comprendidos (ej. \\\"cosa ajena\\\") .", "Verbos como \\\"matar\\\" o \\\"robar\\\".", "La firma del legislador."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿En qué consiste la "tipicidad conglobante" según Zaffaroni?', '["En sumar todos los delitos del país.", "En verificar que la conducta no esté ordenada o fomentada por otra norma del derecho antes de declararla típica .", "En que el tipo sea global para todos los países.", "En el uso de computadoras para juzgar."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es el "dolo"?', '["Una equivocación sin querer.", "El conocimiento y voluntad de realizar los elementos del tipo objetivo [105, 112-115].", "El dolor que siente la víctima.", "La pena de multa impuesta."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Cuál es el "dolo eventual"?', '["Cuando el autor quiere directamente el resultado.", "Cuando el autor se representa el resultado como posible y, aun así, acepta su producción .", "Cuando el autor no sabe lo que hace.", "Un dolo que solo ocurre los domingos."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué caracteriza a la "culpa" o imprudencia?', '["El deseo de matar a alguien.", "La producción de un resultado típico por violación de un deber de cuidado (negligencia, impericia) .", "Es lo mismo que el dolo directo.", "No está penada en Argentina."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es la "culpa consciente" o con representación?', '["El autor quiere el daño.", "El autor se representa el peligro pero confía en que el resultado no ocurrirá por su pericia .", "El autor está dormido mientras actúa.", "Es un dolo de primer grado."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es un "delito de omisión"?', '["Hacer algo prohibido.", "No realizar la conducta mandada por la norma (incumplimiento de un mandato) .", "Olvidarse de pagar los honorarios del abogado.", "Un delito cometido por error."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Cuándo hay "omisión impropia" o comisión por omisión?', '["Cuando se olvida de saludar.", "Cuando un sujeto en posición de garante no evita un resultado dañoso pudiendo hacerlo .", "En el hurto simple.", "Siempre que muere alguien."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es la "antijuridicidad"?', '["El amor por las leyes.", "La contradicción de la conducta típica con el ordenamiento jurídico en su totalidad [102, 130-132].", "La opinión de la policía.", "La falta de abogado defensor."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué son las "causas de justificación"?', '["Mentiras para zafar de la cárcel.", "Preceptos permisivos que eliminan la antijuridicidad de una conducta típica .", "Atenuantes por buena conducta.", "Causas para que el juez se jubile."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Cuál es un requisito de la "Legítima Defensa" (Art. 34 inc 6 CP)?', '["Que el agresor sea un familiar.", "Agresión ilegítima, necesidad racional del medio empleado y falta de provocación suficiente .", "Haber planeado la defensa con un mes de anticipación.", "Que el juez autorice la defensa antes del hecho."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es el "exceso en la legítima defensa" (Art. 35 CP)?', '["Cuando no se defiende.", "Cuando se sobrepasan los límites impuestos por la ley, la autoridad o la necesidad (pena de delito culposo) .", "Defenderse con palabras fuertes.", "Es una causa de justificación plena."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿En qué consiste el "Estado de Necesidad Justificante" (Art. 34 inc 3 CP)?', '["En robar porque se tiene ganas.", "En causar un mal menor para evitar otro mayor e inminente a que ha sido extraño [141, 146-148].", "En defenderse de un ataque a puños con una ametralhadora.", "En cumplir una orden militar ilegal."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Cuál es la diferencia entre Legítima Defensa y Estado de Necesidad?', '["No hay diferencia.", "En la defensa hay agresión ilegítima; en la necesidad hay conflicto entre bienes legítimos [140, 141, 148-150].", "El estado de necesidad solo se aplica en el mar.", "La legítima defensa solo es para el honor."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es el "cumplimiento de un deber" (Art. 34 inc 4 CP)?', '["Una causa de inculpabilidad.", "Una causa de justificación por actuar en cumplimiento de una obligación legal .", "Ir a trabajar todos los días.", "Pagar los impuestos a tiempo."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué efecto tiene el "consentimiento de la víctima" en bienes disponibles?', '["No tiene ningún efecto.", "Elimina la tipicidad o justifica la conducta según el caso .", "Agrava la pena del autor.", "Es un delito autónomo."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es la "justificación putativa"?', '["Una justificación real y legal.", "Creer erróneamente que se actúa bajo una causa de justificación cuando no es así (se resuelve por error) .", "Cuando el juez está de acuerdo con el delincuente.", "Una causa de justificación para el robo."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Es punible el médico que lesiona para salvar una vida (intervención quirúrgica)?', '["Sí, siempre.", "No, por estar justificado en el cumplimiento del deber o ejercicio de su profesión .", "Sí, pero con pena mínima.", "Solo si es un hospital público."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es la "culpabilidad"?', '["El pecado original.", "El reproche personal que se le hace al autor por haber realizado un injusto pudiendo actuar conforme a derecho .", "La cantidad de años de cárcel.", "El sentimiento de tristeza del autor."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Cuál es el primer presupuesto de la culpabilidad?', '["La mayoría de edad solamente.", "La imputabilidad o capacidad de culpabilidad .", "Tener mucho dinero para pagar multas.", "Ser abogado."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Quién es "inimputable" según el Art. 34 inc 1 CP?', '["El que no pudo comprender la criminalidad del acto o dirigir sus acciones .", "El que robó por necesidad económica.", "El que tiene más de 18 años.", "Cualquier persona que esté triste."]'::jsonb, 0, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿A qué edad se establece la plena responsabilidad penal en Argentina?', '["A los 12 años.", "A los 18 años (con régimen especial entre 16 y 18) [172, 175-178].", "A los 21 años.", "A los 14 años."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es la "actio libera in causa"?', '["Un tipo de gimnasia para presos.", "Cuando el sujeto se procura voluntariamente un estado de inimputabilidad para delinquir (responde igual) .", "El derecho a caminar libre por el patio.", "Una causa de justificación para el consumo de drogas."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es el "error de tipo"?', '["Creer que se es un tipo importante.", "El desconocimiento o error sobre los elementos objetivos del tipo (ej. creer que la cosa es propia) .", "No saber que el homicidio es un delito.", "Equivocarse de juzgado."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es el "error de prohibición"?', '["Errar en el tiro al blanco.", "El error sobre la ilicitud o antijuridicidad de la conducta (ej. creer que el hecho está permitido) .", "Robar por error de cálculo.", "No saber el nombre del juez."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué efecto tiene el "error de tipo invencible"?', '["Agrava la pena.", "Elimina el dolo y la tipicidad dolosa (y también la culpa) .", "Solo reduce la multa.", "No tiene ningún efecto jurídico."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es la "obediencia debida" (Art. 34 inc 5 CP)?', '["Obedecer a los padres siempre.", "Una causa de exclusión de responsabilidad por obrar en virtud de un orden jerárquico administrativo .", "Seguir las reglas del fútbol.", "Una orden ilegal que debe cumplirse igual."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es la "coacción" o amenaza de mal grave (Art. 34 inc 2 CP)?', '["Una broma pesada.", "Una causa de inculpabilidad por actuar bajo amenaza de sufrir un mal grave e inminente [148, 195-198].", "El pedido de dinero para un café.", "Un agravante del delito de robo."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es el "iter criminis"?', '["El nombre de un delincuente famoso.", "El camino del delito, desde la ideación hasta el agotamiento .", "El acta de allanamiento.", "La última voluntad del muerto."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Son punibles las ideas o la fase interna del delito?', '["Sí, si son muy malas.", "No, por el principio de que el pensamiento no delinque (cogitationis poenam nemo patitur) [56, 200, 203-205].", "Solo si se cuentan a un cura.", "Sí, en los delitos de terrorismo."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es la "tentativa" (Art. 42 CP)?', '["Desistir de un negocio.", "Comenzar la ejecución de un delito determinado sin llegar a consumarlo por causas ajenas a la voluntad .", "Planear un delito en un cuaderno.", "Un delito cometido por un tentado."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué pena corresponde a la tentativa?', '["La misma que al delito consumado.", "La pena del delito disminuida de un tercio a la mitad .", "Solo una multa de 10 pesos.", "Prisión perpetua siempre."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es el "desistimiento voluntario" (Art. 43 CP)?', '["Cuando la policía atrapa al ladrón.", "Cuando el autor de tentativa abandona el delito voluntariamente (no está sujeto a pena) .", "Cuando el abogado renuncia a la causa.", "El olvido de la víctima."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es el "delito imposible"?', '["Un delito que no se puede leer.", "Una tentativa inidónea por los medios empleados o el objeto (ej. disparar a un muerto) [204, 210, 212-214].", "El robo de un banco por un solo hombre.", "Un delito cometido por un superhéroe."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Quién es el "autor" del delito?', '["Solo el que escribe libros.", "Quien realiza la acción típica o tiene el dominio del hecho .", "El que mira cómo roban.", "El dueño de la cárcel."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es la "autoría mediata"?', '["Ser autor a medias.", "Valerse de otra persona que no comete injusto (inimputable o coaccionado) como instrumento .", "Robar a través de internet.", "Un delito cometido por periodistas."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Quiénes son "coautores"?', '["Los que se prestan las herramientas.", "Quienes realizan el hecho conjuntamente mediante una división de tareas (dominio funcional) .", "Los familiares del delincuente.", "El público que aplaude el delito."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es el "instigador" (Art. 45 CP)?', '["El que ayuda a escapar.", "Quien determina directamente a otro a cometer un delito .", "El que limpia la escena del crimen.", "El juez que dicta sentencia."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es el "cómplice necesario" (primario)?', '["El que presta un auxilio sin el cual el hecho no habría podido cometerse (pena de autor) .", "El que llega tarde al robo.", "El que llama a la ambulancia.", "El que presta el auto por comodidad."]'::jsonb, 0, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué pena tiene el "cómplice no necesario" (secundario)?', '["Pena de muerte.", "La pena del delito disminuida de un tercio a la mitad (Art. 46 CP) .", "Queda libre de inmediato.", "El doble que el autor."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es la "accesoriedad limitada" en la participación?', '["Que el participe no viaja en el auto del autor.", "Que para castigar al participe basta que el autor haya realizado un injusto (típico y antijurídico) .", "Que el cómplice debe ser un amigo íntimo.", "Que la participación es opcional."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es el "Concurso Ideal" (Art. 54 CP)?', '["Un concurso de belleza en la cárcel.", "Cuando un solo hecho cae bajo más de una sanción penal (se aplica la pena mayor) .", "Robar dos veces en el mismo lugar.", "El sueño de todo delincuente."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es el "Concurso Real" (Art. 55 CP)?', '["Un concurso organizado por el Rey.", "Cuando concurren varios hechos independientes cometidos por la misma persona .", "El robo de una corona real.", "Un delito que realmente ocurrió."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Cómo se aplica la pena en el "Concurso Real"?', '["Se suman todas las penas sin límite.", "Suma aritmética de las máximas (tope 50 años) y el mínimo mayor (Art. 55 CP) .", "Se aplica solo la pena más chica.", "El juez elige la pena que quiera."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es el "delito continuado"?', '["Un delito que dura 24 horas.", "Pluralidad de actos que lesionan la misma ley con unidad de dolo o resolución (se juzga como uno solo) [200, 248-250].", "Estar preso por 10 años seguidos.", "Un delito que no tiene fin."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es el "Concurso Aparente" de leyes?', '["Cuando parece que hay un delito pero no.", "Cuando una conducta parece encuadrar en varios tipos pero uno desplaza a los otros (especialidad, consunción) .", "El uso de disfraces para delinquir.", "Un error del legislador al escribir el Código."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es el principio de "Especialidad" en los concursos?', '["Ser un especialista en robos.", "La ley especial deroga a la general (ej. homicidio agravado desplaza al simple) .", "Que el juez debe ser penalista.", "Un tipo de fianza especial."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es el principio de "Consunción"?', '["El consumo de drogas prohibidas.", "Un tipo delictivo absorbe el desvalor de otro (ej. el homicidio consume las lesiones previas) .", "La quema de pruebas.", "El fin de la pena por tiempo."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Cuáles son las penas principales del Código Penal argentino (Art. 5 CP)?', '["Destierro y azotes.", "Reclusión, prisión, multa e inhabilitación [243, 257-260].", "Trabajos comunitarios solamente.", "Pena de muerte y tortura."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Cuál es la pena más grave en Argentina después de la reclusión?', '["La inhabilitación.", "La prisión [243, 261-264].", "La multa.", "El llamado de atención."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿En qué consiste la "inhabilitación absoluta" (Art. 19 CP)?', '["En no poder caminar por la calle.", "Privación de empleo público, derecho electoral, jubilación y cargos .", "En que el reo no puede hablar con nadie.", "En el cierre de su cuenta bancaria."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es la "multa" (Art. 21 CP)?', '["Un regalo para el juez.", "La obligación de pagar una suma de dinero al Estado por el delito cometido .", "Un pago directo a la víctima.", "Un impuesto municipal."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué sucede si el reo no paga la multa?', '["Se lo perdona.", "Sufre prisión que no excederá de año y medio (conversión) .", "El Estado le quita a los hijos.", "Se le prohíbe comer."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es la "Condena de Ejecución Condicional" (Art. 26 CP)?', '["Estar preso solo los fines de semana.", "Suspensión de la ejecución de la prisión (si no excede 3 años) para delincuentes primarios .", "Una condena que se cumple en el aire.", "Una condena para extranjeros."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es la "Libertad Condicional" (Art. 13 CP)?', '["Salir a pasear con permiso policial.", "Egreso anticipado del establecimiento bajo condiciones tras cumplir parte de la condena [277, 278, 280-282].", "Que el preso elija su celda.", "Es un derecho absoluto que se gana al entrar."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿A quiénes se les deniega la Libertad Condicional (Art. 14 CP)?', '["A los que no saben leer.", "A los reincidentes y autores de ciertos delitos graves (ej. homicidio criminis causa) [277, 283-286].", "A los extranjeros.", "A los menores de edad."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es la "Reincidencia" (Art. 50 CP)?', '["Robar el mismo objeto dos veces.", "Cometer un nuevo delito tras haber cumplido total o parcialmente una pena privativa de libertad anterior [284, 286-289].", "Ser hijo de un delincuente.", "Entrar a la cárcel sin condena."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Cuál es la causa de extinción de la acción penal por muerte (Art. 59 CP)?', '["La muerte de la víctima únicamente.", "La muerte del imputado .", "La muerte del juez.", "La muerte de un testigo."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es la "Prescripción"?', '["Una receta médica para el reo.", "La extinción de la acción o la pena por el solo transcurso del tiempo fijado por ley .", "La orden del médico de la cárcel.", "Un tipo de fianza en efectivo."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué interrumpe la prescripción de la acción penal?', '["El pedido de disculpas.", "La comisión de un nuevo delito o actos procesales como el llamado a indagatoria o sentencia .", "Las vacaciones del fiscal.", "El cambio de abogado."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es el "Indulto" (Art. 68 CP)?', '["Un insulto al delincuente.", "El perdón de la pena otorgado por el Poder Ejecutivo [292, 297-299].", "La libertad por cumplimiento total.", "Un beneficio para pagar la multa en cuotas."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es la "Amnistía"?', '["Una amnesia colectiva.", "El olvido de un hecho delictivo por razones políticas, dictado por el Congreso [291, 292, 299-301].", "Un tipo de inhabilitación especial.", "El permiso para salir del país."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10124', 'Derecho Penal I', 'media', '¿Qué es la "Unificación de penas" (Art. 58 CP)?', '["Usar el mismo uniforme para todos los presos.", "El procedimiento judicial para dictar una sentencia única a quien tiene varias condenas o procesos [189, 296, 302-305].", "Pagar todas las multas en un solo banco.", "Que todos los delitos tengan la misma pena."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Penal I.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10125', 'Derecho Constitucional', 'media', '¿Cuál es el enfoque tradicional del derecho constitucional según Linares Quintana?', '["Una disciplina de las ciencias políticas .", "Una rama del derecho que estudia la constitución .", "El estudio de las relaciones internacionales del Estado .", "Una rama de la sociología jurídica ."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Constitucional.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10125', 'Derecho Constitucional', 'media', '¿A qué campo de las ciencias pertenece el Derecho Constitucional según el Apunte de Cátedra III?', '["Ciencias exactas o naturales .", "Ciencias ideales o abstractas .", "Ciencias reales, materiales o de la cultura .", "Ciencias formales y lógicas ."]'::jsonb, 2, 'Conforme a la doctrina y jurisprudencia de Derecho Constitucional.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10125', 'Derecho Constitucional', 'media', '¿Cuál es el objeto de estudio de la Ciencia Política según las tendencias actuales?', '["El estudio exclusivo de las normas jurídicas .", "El poder que se ejerce dentro y fuera del Estado .", "La redacción de las constituciones mundiales .", "La historia de las monarquías absolutas ."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Constitucional.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10125', 'Derecho Constitucional', 'media', '¿Qué técnica estudia las decisiones políticas mediante la utilización de recursos matemáticos?', '["El comportamiento político .", "La teoría de los juegos .", "La interpretación teleológica .", "El monismo absoluto ."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Constitucional.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10125', 'Derecho Constitucional', 'media', '¿Qué postulado del constitucionalismo moderno implica que la ley está por encima de todas las demás?', '["Principio de reserva .", "Control de convencionalidad .", "Supremacía constitucional .", "Enumeración de derechos ."]'::jsonb, 2, 'Conforme a la doctrina y jurisprudencia de Derecho Constitucional.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10125', 'Derecho Constitucional', 'media', '¿En qué año se dictó la primera constitución de los Estados Unidos (Filadelfia)?', '["1776 .", "1787 .", "1791 .", "1810 ."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Constitucional.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10125', 'Derecho Constitucional', 'media', '¿Qué documento inglés de 1215 es considerado un antecedente remoto que limitaba al Rey?', '["La Petición de Derechos .", "El Acta de Establecimiento .", "La Carta Magna .", "El Estatuto de Límites ."]'::jsonb, 2, 'Conforme a la doctrina y jurisprudencia de Derecho Constitucional.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10125', 'Derecho Constitucional', 'media', '¿Cuál es la característica central del constitucionalismo social surgido en el siglo XX?', '["Proteger exclusivamente los derechos individuales .", "La abstención total del Estado en la economía .", "Incluir protecciones a grupos como trabajadores, mujeres, niños y ancianos .", "La centralización absoluta del poder en el ejecutivo ."]'::jsonb, 2, 'Conforme a la doctrina y jurisprudencia de Derecho Constitucional.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10125', 'Derecho Constitucional', 'media', '¿Qué constitución de 1917 es citada como el primer ejemplo de constitucionalismo social?', '["Constitución de Weimar .", "Constitución de Filadelfia .", "Constitución de México .", "Constitución de Cádiz ."]'::jsonb, 2, 'Conforme a la doctrina y jurisprudencia de Derecho Constitucional.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10125', 'Derecho Constitucional', 'media', '¿Cómo define Lasalle a la Constitución "Real"?', '["El documento escrito con numeración de artículos .", "La suma de los factores reales de poder que rigen en una nación .", "Una norma racional que determina las funciones del Estado .", "La continuidad de la costumbre de una sociedad ."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Constitucional.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10125', 'Derecho Constitucional', 'media', '¿Qué tipología de García Pelayo entiende la constitución como el "devenir histórico"?', '["Racional-Normativa .", "Sociológica .", "Histórico-Tradicional .", "Pétrea ."]'::jsonb, 2, 'Conforme a la doctrina y jurisprudencia de Derecho Constitucional.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10125', 'Derecho Constitucional', 'media', '¿Qué clase de constitución se modifica mediante procedimientos especiales y dificultosos?', '["Flexible .", "Rígida .", "Dispersa .", "Utilitaria ."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Constitucional.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10125', 'Derecho Constitucional', 'media', '¿Cuál es el orden de supremacía federal según el artículo 31 de la CN?', '["Constitución, Leyes, Tratados .", "Tratados, Constitución, Leyes .", "Constitución Nacional, Tratados, Leyes, Decretos .", "Leyes, Tratados, Constitución ."]'::jsonb, 2, 'Conforme a la doctrina y jurisprudencia de Derecho Constitucional.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10125', 'Derecho Constitucional', 'media', '¿Qué es el control de constitucionalidad "Difuso"?', '["El realizado por un tribunal constitucional específico .", "El realizado por todos los jueces de cualquier instancia .", "El que solo puede ejercer el Poder Legislativo .", "El que se aplica únicamente a los tratados internacionales ."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Constitucional.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10125', 'Derecho Constitucional', 'media', '¿Qué efecto tiene en el orden federal argentino la declaración de inconstitucionalidad de una norma?', '["Derogación general de la ley .", "Aplicación de la ley marcial .", "La no aplicación de la ley solo en el caso concreto .", "La destitución automática del legislador que la creó ."]'::jsonb, 2, 'Conforme a la doctrina y jurisprudencia de Derecho Constitucional.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10125', 'Derecho Constitucional', 'media', '¿Qué tipo de poder constituyente es el que dicta la primera constitución de un Estado?', '["Derivado .", "Federal de segundo grado .", "Originario .", "Municipal ."]'::jsonb, 2, 'Conforme a la doctrina y jurisprudencia de Derecho Constitucional.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10125', 'Derecho Constitucional', 'media', '¿Qué mayoría se requiere en el Congreso para declarar la necesidad de una reforma constitucional (Art. 30)?', '["Mayoría simple de los presentes .", "Las dos terceras partes de los miembros .", "Unanimidad de ambas cámaras .", "Mayoría absoluta de los totales ."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Constitucional.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10125', 'Derecho Constitucional', 'media', '¿Quién es el titular del Poder Constituyente en nuestro sistema democrático?', '["El Presidente de la Nación .", "El Congreso .", "El pueblo .", "La Corte Suprema ."]'::jsonb, 2, 'Conforme a la doctrina y jurisprudencia de Derecho Constitucional.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10125', 'Derecho Constitucional', 'media', '¿Qué pacto preexistente de 1852 es fundamental para la reunión del Congreso General Constituyente?', '["Pacto de Pilar .", "Pacto Federal .", "Acuerdo de San Nicolás .", "Pacto de San José de Flores ."]'::jsonb, 2, 'Conforme a la doctrina y jurisprudencia de Derecho Constitucional.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10125', 'Derecho Constitucional', 'media', '¿Cuál es la función del Preámbulo según la jurisprudencia de la CSJN?', '["Es la primera ley operativa de la nación .", "Tiene un fin meramente decorativo .", "Tiene un fin interpretativo y explica los objetivos de la constitución .", "Determina la culpabilidad en los juicios penales ."]'::jsonb, 2, 'Conforme a la doctrina y jurisprudencia de Derecho Constitucional.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10125', 'Derecho Constitucional', 'media', '¿Qué reforma constitucional incorporó el artículo 14 bis?', '["1860 .", "1949 .", "1957 .", "1994 ."]'::jsonb, 2, 'Conforme a la doctrina y jurisprudencia de Derecho Constitucional.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10125', 'Derecho Constitucional', 'media', '¿Qué cambio introdujo la reforma de 1994 respecto a la elección del Presidente?', '["Elección por colegios electorales .", "Elección directa con sistema de doble vuelta (ballotage) .", "Elección a través del Congreso Nacional .", "Elección vitalicia sin reelección ."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Constitucional.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10125', 'Derecho Constitucional', 'media', '¿Cuántos senadores por provincia establece la constitución tras la reforma de 1994?', '["Dos por la mayoría .", "Tres senadores (dos por la mayoría, uno por la minoría) .", "Uno por cada 100.000 habitantes .", "Cinco elegidos por el gobernador ."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Constitucional.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10125', 'Derecho Constitucional', 'media', '¿Qué mayoría se necesita para la elección de los jueces de la Corte Suprema por el Senado?', '["Mayoría simple .", "Dos terceras partes de los presentes .", "Unanimidad .", "Mayoría absoluta de los totales ."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Constitucional.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10125', 'Derecho Constitucional', 'media', '¿Cómo define Mayón la forma de Estado argentina en relación a otros países?', '["Unitaria centralizada .", "Federal, más federal que Sudáfrica pero menos que EE.UU. .", "Confederación de estados soberanos .", "Monarquía parlamentaria ."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Constitucional.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10125', 'Derecho Constitucional', 'media', '¿Qué establece el artículo 20 de la CN respecto a los extranjeros?', '["Tienen prohibido ejercer el comercio .", "Gozan de los mismos derechos civiles que el ciudadano .", "Están obligados a defender la patria con las armas .", "Solo pueden habitar en la Capital Federal ."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Constitucional.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10125', 'Derecho Constitucional', 'media', '¿Cuál es la causa que justifica la Intervención Federal en una provincia (Art. 6)?', '["El pedido del gobernador para aumentar impuestos .", "Un ataque exterior o conmoción interior que afecte la forma republicana .", "La falta de presupuesto municipal .", "La simple voluntad discrecional del Presidente ."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Constitucional.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10125', 'Derecho Constitucional', 'media', '¿Qué suspende la declaración del Estado de Sitio (Art. 23)?', '["La vigencia de la Constitución .", "La autonomía de las provincias .", "Las libertades individuales de forma limitada .", "El cobro de los impuestos federales ."]'::jsonb, 2, 'Conforme a la doctrina y jurisprudencia de Derecho Constitucional.', 100);
