INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10125', 'Derecho Constitucional', 'media', '¿Qué tributo se paga al Estado para recibir una contraprestación proporcionada (asfalto, luz, etc.)?', '["Impuesto .", "Tasa .", "Contribución Especial .", "Empréstito ."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Constitucional.', 100);
