INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10125', 'Derecho Constitucional', 'media', '¿Qué son los derechos "Implícitos" según el artículo 33 de la CN?', '["Los enumerados taxativamente en el texto .", "Los que nacen de la soberanía del pueblo y de la forma republicana .", "Derechos que han perdido vigencia .", "Normas que el Congreso aún no ha redactado ."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Constitucional.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10125', 'Derecho Constitucional', 'media', '¿Cómo define la doctrina los derechos "Personalísimos"?', '["Derechos que se pueden transferir a cambio de dinero .", "Derechos subjetivos esenciales, innatos e inherentes a la naturaleza humana (vida, honor, etc.) .", "Garantías que solo tienen los abogados .", "Derechos que nacen únicamente con la mayoría de edad ."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Constitucional.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10125', 'Derecho Constitucional', 'media', '¿Qué estableció la CSJN en el fallo "F.A.L." (2012)?', '["El derecho absoluto a la eutanasia .", "El aborto no punible en casos de violación sin necesidad de trámite judicial .", "La prohibición de toda transfusión de sangre .", "La obligatoriedad de la enseñanza religiosa en las escuelas ."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Constitucional.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10125', 'Derecho Constitucional', 'media', '¿Qué fallo de la CSJN protegió el derecho a la intimidad frente a una foto publicada de un dirigente político enfermo?', '["Fallo Ekmekdjian c/ Sofovich .", "Fallo Ponzetti de Balbín .", "Fallo Marbury v. Madison .", "Fallo Bazterrica ."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Constitucional.', 100);
INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10125', 'Derecho Constitucional', 'media', '¿Qué implica el principio de "igualdad ante la ley" (Igualdad Formal)?', '["Que todos deben cobrar el mismo sueldo .", "Igual tratamiento para los iguales en iguales circunstancias .", "Que no puede haber distinción entre niños y adultos .", "La eliminación de los sindicatos ."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Constitucional.', 100);
