INSERT INTO public.db_trivia_questions (id_categoria, categoria_nombre, dificultad, pregunta, opciones, respuesta_correcta_index, fundamento_juridico, puntos_base) VALUES ('10125', 'Derecho Constitucional', 'media', '¿En qué consiste el "derecho a réplica" aplicado en el fallo Ekmekdjian c/ Sofovich?', '["En el derecho a insultar a quien nos insultó .", "En utilizar el mismo medio de difusión para aclarar o reparar un agravio erróneo .", "En exigir el cierre del canal de televisión .", "En cobrar una indemnización monetaria inmediata sin rectificación ."]'::jsonb, 1, 'Conforme a la doctrina y jurisprudencia de Derecho Constitucional.', 100);
